class RaisingOnChunkReadStore(MutableMapping):
    def __init__(self, inner):
        self.inner = inner
        self.read_chunk = False

    def _is_chunk_key(self, key: str) -> bool:
        # chunk keys are like "foo/0" or "foo/0.0" etc. We allow metadata keys.
        if key.startswith("foo/") and not key.startswith("foo/."):
            # allow .zarray/.zattrs inside foo
            if key in ("foo/.zarray", "foo/.zattrs"):
                return False
            return True
        return False

    def __getitem__(self, key):
        if self._is_chunk_key(key):
            self.read_chunk = True
            raise RuntimeError(f"unexpected chunk read: {key}")
        return self.inner[key]

    def __setitem__(self, key, value):
        self.inner[key] = value

    def __delitem__(self, key):
        del self.inner[key]

    def __iter__(self):
        return iter(self.inner)

    def __len__(self):
        return len(self.inner)

    def getitems(self, keys, **kwargs):
        out = {}
        for k in keys:
            try:
                out[k] = self[k]
            except KeyError:
                if kwargs.get("on_error") == "raise":
                    raise
            except RuntimeError:
                # propagate our chunk-read error
                raise
        return out

