def get_chunksizes(
    variables: Iterable[Variable],
) -> Mapping[Any, tuple[int, ...]]:

    # Avoid touching Variable.data here.
    #
    # Variable.data may coerce some lazily indexed backend arrays (e.g. zarr
    # wrappers) into a NumPy array via Variable.values, which can trigger IO and
    # load the full array into memory. Chunk metadata, when present, lives on
    # the underlying (dask) array as the ``.chunks`` attribute, so we only need
    # to inspect ``Variable._data``.
    chunks: dict[Any, tuple[int, ...]] = {}
    for v in variables:
        v_chunks = getattr(v._data, "chunks", None)
        if v_chunks is None:
            continue

        for dim, c in zip(v.dims, v_chunks):
            if dim in chunks and c != chunks[dim]:
                raise ValueError(
                    f"Object has inconsistent chunks along dimension {dim}. "
                    "This can be fixed by calling unify_chunks()."
                )
            chunks[dim] = c

    return Frozen(chunks)


def is_np_datetime_like(dtype: DTypeLike) -> bool:
    """Check if a dtype is a subclass of the numpy datetime types"""
    return np.issubdtype(dtype, np.datetime64) or np.issubdtype(dtype, np.timedelta64)


def is_np_timedelta_like(dtype: DTypeLike) -> bool:
    """Check whether dtype is of the timedelta64 dtype."""
    return np.issubdtype(dtype, np.timedelta64)

